import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import DatePickerInput from './DatePickerInput';
import { formatedDate } from './utils';

describe('DatePickerInput', () => {
  describe('Input', () => {
    test('should render input with label', () => {
      render(<DatePickerInput label="Name" />);
      expect(screen.getByText('Name')).toBeInTheDocument();
    });

    test('should not call callback function with the actual value when something is typed but it is not passed a onChange argument', () => {
      render(<DatePickerInput label="Name" data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      fireEvent.change(input, { target: { value: 'abc' } });
      expect(screen.getByText('Name')).toBeInTheDocument();
    });

    test('should render input with hint text', () => {
      render(<DatePickerInput label="Label" hint="Hint Text" />);
      expect(screen.getByText('Hint Text')).toBeInTheDocument();
    });

    test('should render disabled input', () => {
      render(<DatePickerInput label="Label" disabled />);
      expect(screen.getByText('Label')).toBeInTheDocument();
    });

    test('should render input without label', () => {
      render(<DatePickerInput placeholder="placeholder" />);
      expect(screen.queryByText('placeholder')).not.toBeInTheDocument();
    });

    test('should render input with error text', () => {
      render(<DatePickerInput label={false} errorText="Error Text" hasError />);
      expect(screen.getByText('Error Text')).toBeInTheDocument();
    });

    test('should render input with error text even when disabled', () => {
      render(
        <DatePickerInput
          label="Label"
          errorText="Error Text"
          hasError
          disabled
          data-testid="input-test"
        />
      );
      const input = screen.getByTestId('input-test');
      expect(screen.getByText('Error Text')).toBeInTheDocument();
      expect(input.disabled).toBe(true);
    });

    test('should render input with legend text', () => {
      render(<DatePickerInput label={false} legend="Legend" />);
      expect(screen.getByText('Legend')).toBeInTheDocument();
    });

    test('should render input with default value when mode is single', () => {
      const date = new Date('03/01/2023');
      render(<DatePickerInput value={[date]} data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      expect(input.value).toBe(
        formatedDate(date.toString(), {
          month: 'short',
          day: '2-digit',
          year: 'numeric',
        })
      );
    });

    test('should render input with default value when mode is range', () => {
      const range = [new Date('03/01/2023'), new Date('03/10/2023')];
      render(<DatePickerInput value={range} data-testid="input-test" mode="range" />);
      const input = screen.getByTestId('input-test');
      expect(input.value).toBe(
        `${formatedDate(range[0].toString(), {
          month: 'short',
          day: '2-digit',
          year: 'numeric',
        })} to ${formatedDate(range[1].toString(), {
          month: 'short',
          day: '2-digit',
          year: 'numeric',
        })}`
      );
    });

    test('should render (Optional) text when has a label and it is not required', () => {
      render(<DatePickerInput label="Label" required={false} />);
      expect(screen.getByText('(Optional)')).toBeInTheDocument();
    });
  });
});
